CREATE TABLE "product_compatibility" ("component_id" TEXT NOT NULL, "device_id" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "product_compatibility_pkey" PRIMARY KEY ("component_id", "device_id"), CONSTRAINT "product_compatibility_component_fkey" FOREIGN KEY ("component_id") REFERENCES "products"("id") ON DELETE CASCADE, CONSTRAINT "product_compatibility_device_fkey" FOREIGN KEY ("device_id") REFERENCES "products"("id") ON DELETE CASCADE);
ALTER TABLE "product_categories" ADD COLUMN "parent_id" UUID;
ALTER TABLE "product_categories" ADD CONSTRAINT "product_categories_parent_fkey" FOREIGN KEY ("parent_id") REFERENCES "product_categories"("id") ON DELETE SET NULL;
CREATE TABLE "rental_units" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "product_id" TEXT NOT NULL, "serial" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'san_sang', "location" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "rental_units_pkey" PRIMARY KEY ("id"), CONSTRAINT "rental_units_serial_key" UNIQUE ("serial"), CONSTRAINT "rental_units_product_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id"));
CREATE TYPE "RentalUnitStatus" AS ENUM ('san_sang', 'dang_thue', 'bao_tri');
ALTER TABLE "rental_units" ALTER COLUMN "status" DROP DEFAULT;
ALTER TABLE "rental_units" ALTER COLUMN "status" TYPE "RentalUnitStatus" USING "status"::"RentalUnitStatus";
ALTER TABLE "rental_units" ALTER COLUMN "status" SET DEFAULT 'san_sang';
CREATE INDEX "rental_units_product_status_idx" ON "rental_units"("product_id", "status");
CREATE TABLE "rental_unit_bookings" ("rental_id" UUID NOT NULL, "unit_id" UUID NOT NULL, CONSTRAINT "rental_unit_bookings_pkey" PRIMARY KEY ("rental_id", "unit_id"), CONSTRAINT "rental_unit_bookings_rental_fkey" FOREIGN KEY ("rental_id") REFERENCES "rentals"("id") ON DELETE CASCADE, CONSTRAINT "rental_unit_bookings_unit_fkey" FOREIGN KEY ("unit_id") REFERENCES "rental_units"("id"));
CREATE TABLE "inventory_logs" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "unit_id" UUID, "product_id" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "reason" TEXT, "user_id" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "inventory_logs_pkey" PRIMARY KEY ("id"), CONSTRAINT "inventory_logs_unit_fkey" FOREIGN KEY ("unit_id") REFERENCES "rental_units"("id"), CONSTRAINT "inventory_logs_product_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id"), CONSTRAINT "inventory_logs_user_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id"));
CREATE INDEX "inventory_logs_product_created_idx" ON "inventory_logs"("product_id", "created_at");
